"use client";

import * as React from "react";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { cn } from "@/lib/utils";
import { withDirectionalPortal } from "@/components/ui/direction-provider";

const PopoverPortal = withDirectionalPortal(PopoverPrimitive.Portal);
const Popover = PopoverPrimitive.Root;
const PopoverTrigger = PopoverPrimitive.Trigger;
const PopoverAnchor = PopoverPrimitive.Anchor;

const PopoverContent = React.forwardRef<
  React.ElementRef<typeof PopoverPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content>
>(({ className, align = "center", sideOffset = 4, "aria-label": ariaLabel, "aria-labelledby": ariaLabelledBy, ...props }, ref) => (
  <PopoverPortal>
    <PopoverPrimitive.Content
      ref={ref}
      align={align}
      sideOffset={sideOffset}
      // Radix gives this `role="dialog"`, and a dialog without an accessible name is announced as just
      // "dialog" — WCAG 4.1.2. Nothing here named it, so every Popover in the library shipped that way:
      // found by running axe against the surface while it was open, which until this slice nothing did.
      // The fallback is deliberately only a fallback. A caller who passes `aria-label` or points at a
      // heading with `aria-labelledby` keeps theirs, and should: "Popover" tells a screen-reader user
      // what kind of thing opened and nothing about what is in it. It is the floor, not the goal.
      // Both naming props are destructured OUT of the spread, not read from it. Read from `props` with
      // `{...props}` trailing, `aria-label={label}` with `label` undefined — the ordinary conditional-prop
      // spelling — spreads the key back as undefined and deletes the attribute, so the fallback computed
      // here would be erased and the dialog would ship unnamed again by the very pattern it guards.
      aria-labelledby={ariaLabelledBy}
      aria-label={ariaLabel ?? (ariaLabelledBy ? undefined : "Popover")}
      className={cn(
        // A surface wider than the window is not usable. Measured at 390px with the root font size
        // doubled: this came out 576px, because `w-72` is rem and doubles with the text, and the
        // context menu 416px — pushing the page 186px sideways, so a reader who asked for large text
        // had to scroll horizontally to see a popover. Radix publishes the room it has as
        // `--radix-popper-available-width`, so the cap is its own measurement rather than a viewport
        // guess, and it binds only when the surface would otherwise overflow.
        "z-overlay w-72 max-w-[var(--radix-popper-available-width)] rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-none font-sans",
        "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=open]:duration-fast data-[state=open]:ease-enter data-[state=closed]:duration-instant data-[state=closed]:ease-exit",
        // `data-side` is the side Radix RESOLVED the surface onto — it is already physical, having been
        // flipped for direction and collisions before it reaches the DOM. The slide must therefore stay
        // physical to travel away from the trigger; a logical class here would invert the animation under
        // RTL and make the surface fly the wrong way. // rtl-ok
        "data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
        className,
      )}
      {...props}
    />
  </PopoverPortal>
));
PopoverContent.displayName = PopoverPrimitive.Content.displayName;

export { Popover, PopoverTrigger, PopoverContent, PopoverAnchor };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
